 def pic_proxy(self,u):
  u=htmllib.unescape(u or '').replace('&#x2F;','/').replace('&#x3D;','=')
  q=urllib.parse.parse_qs(urllib.parse.urlparse(u).query).get('url',[''])[0] if 'api/proxy' in u and 'url=' in u else u
  if q.startswith('//'): q='https:'+q
  return 'https://ig2.pppppppp.top/api/proxy?url='+q if q.startswith('http') else u
 def parse_list(self,html):
  arr=[];seen=set()
  for m in re.finditer(r'<a\s+href="/([a-z0-9][a-z0-9_-]{2,})"[^>]*>',html,re.S|re.I):
   vid=m.group(1)
   if vid in seen or vid in ['login','history','new','release','genres','actresses','makers','today-hot','weekly-hot','monthly-hot']: continue
   block=html[m.start():m.start()+2600];title=vid.upper()
   tm=re.search(r'<a class="text-secondary[^>]*href="/'+re.escape(vid)+r'"[^>]*>(.*?)</a>',block,re.S)
   if tm: title=self.title_clean(tm.group(1))
   if len(title)<2 or '更多' in title: continue
   pic='';pm=re.search(r'(?:data-src|src)="([^"]*(?:cover-[tn]\.jpg|cover\.jpg|/1\.jpg)[^"]*)"',block,re.I)
   if pm: pic=self.pic_proxy(pm.group(1))
   if not pic: pic=self.pic_proxy('https://fourhoi.com/'+vid+'/cover-t.jpg')
   dur='';dm=re.search(r'<span[^>]*>(\s*\d{1,2}:\d{2}(?::\d{2})?\s*)</span>',block,re.S)
   if dm: dur=dm.group(1).strip()
   arr.append({'vod_id':vid,'vod_name':title,'vod_pic':pic,'vod_remarks':dur});seen.add(vid)
  return arr
